#!/usr/bin/env python3
"""Writes the small synthetic G-code fixtures of the reader tests into ./gcode/.

Every value is invented. The files imitate only the layout and the key names that real
slicer output showed (header, preview blocks, sums, settings block); none of them is copied
from a real or downloaded file, and each is a few KiB. Reproducible byte for byte:

    python3 make_synthetic_gcode.py            # writes ./gcode/*
"""
import base64
import os
import struct
import zlib


def png(width=1, height=1, rgb=(200, 30, 30)):
    """A valid PNG of one color (the reader only checks signature and size)."""
    def chunk(kind, data):
        body = kind + data
        return struct.pack(">I", len(data)) + body + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF)
    raw = b"".join(b"\x00" + bytes(rgb) * width for _ in range(height))
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b""))


def thumbnail_block(width, height, data, begin="thumbnail begin", end="thumbnail end", wrap=78):
    text = base64.b64encode(data).decode()
    lines = [text[i:i + wrap] for i in range(0, len(text), wrap)]
    out = [f"; {begin} {width}x{height} {len(text)}"] + [f"; {l}" for l in lines] + [f"; {end}"]
    return "\n".join(out) + "\n"


BODY = "".join(f"G1 X{10 + i}.0 Y{20 + i}.0 E{i}.25 F1800\n" for i in range(30))


def prusa(two_filaments):
    n = 2 if two_filaments else 1
    pair = lambda a, b, sep=",": sep.join([a, b][:n])
    head = ("; generated by PrusaSlicer 9.9.9+linux-x64-GTK3 on 2030-01-02 at 03:04:05 UTC\n\n\n;\n"
            + thumbnail_block(16, 16, png(1, 1), "thumbnail_QOI begin", "thumbnail_QOI end")
            + thumbnail_block(220, 124, png(2, 2))
            + ";\n; external perimeters extrusion width = 0.45mm\n\nG28\n")
    tail = (BODY + "; filament used [mm] = " + pair("1372.73", "1371.79", ", ") + "\n"
            + "; filament used [cm3] = " + pair("3.30", "3.30", ", ") + "\n"
            + "; filament used [g] = " + pair("4.09", "4.19", ", ") + "\n"
            + "; filament cost = " + pair("0.10", "0.13", ", ") + "\n"
            + ("; total filament used [g] = 8.28\n" if two_filaments else "; total filament used [g] = 4.09\n")
            + "; estimated printing time (normal mode) = 1h 9m 37s\n"
            + "; estimated printing time (silent mode) = 1h 10m 1s\n"
            + "; estimated first layer printing time (normal mode) = 1m 35s\n\n"
            + "; prusaslicer_config = begin\n"
            + "; bed_temperature = " + pair("60", "70") + "\n"
            + "; filament_colour = " + pair("#E4002B", '"#00AA00"', ";") + "\n"
            + "; filament_type = " + pair("PLA", "PETG", ";") + "\n"
            + "; layer_height = 0.2\n"
            + "; nozzle_diameter = " + pair("0.4", "0.4") + "\n"
            + "; printer_model = MK4S\n"
            + "; temperature = " + pair("215", "235") + "\n"
            + "; prusaslicer_config = end\n")
    return head + tail


def orca_head(with_sums_line=True):
    return ("; HEADER_BLOCK_START\n; generated by OrcaSlicer 9.9.9 on 2030-01-02 at 03:04:05\n"
            "; total layer number: 100\n; filament_density: 1.24\n; filament_diameter: 1.75\n"
            "; max_z_height: 20.00\n; filament: 1\n; HEADER_BLOCK_END\n\n"
            "; THUMBNAIL_BLOCK_START\n\n;\n" + thumbnail_block(96, 96, png(1, 1)) + "; THUMBNAIL_BLOCK_END\n\n"
            "; THUMBNAIL_BLOCK_START\n\n;\n" + thumbnail_block(300, 300, png(3, 3)) + "; THUMBNAIL_BLOCK_END\n\n"
            "; EXECUTABLE_BLOCK_START\nM73 P0 R15\n" + BODY + "; EXECUTABLE_BLOCK_END\n\n")


def orca():
    return (orca_head() + "; filament used [mm] = 1211.31\n; filament used [cm3] = 2.91\n; filament used [g] = 3.61\n"
            "; filament cost = 0.07\n; total filament used [g] = 3.61\n; total filament cost = 0.07\n"
            "; total layers count = 100\n; estimated printing time (normal mode) = 15m 19s\n"
            "; estimated first layer printing time (normal mode) = 10s\n\n"
            "; CONFIG_BLOCK_START\n; curr_bed_type = High Temp Plate\n; filament_colour = #56DF3D\n"
            "; filament_type = PLA\n; hot_plate_temp = 55\n; layer_height = 0.2\n; nozzle_diameter = 0.4\n"
            "; nozzle_temperature = 220\n; printer_model = Example Printer X\n; textured_plate_temp = 99\n"
            "; CONFIG_BLOCK_END\n")


def orca_header_only():
    return orca_head()


def bambu():
    return ("; HEADER_BLOCK_START\n; BambuStudio 99.99.99.99\n"
            "; model printing time: 2h 18m 33s; total estimated time: 2h 18m 52s\n; total layer number: 100\n"
            "; total filament length [mm] : 5197.96,7153.11\n; total filament volume [cm^3] : 12502.57,17205.25\n"
            "; total filament weight [g] : 15.75,21.68\n; model label id: 47,58\n; filament_density: 1.26,1.26\n"
            "; filament_diameter: 1.75,1.75\n; max_z_height: 20.00\n; filament: 1,2\n; HEADER_BLOCK_END\n\n"
            "; CONFIG_BLOCK_START\n; cool_plate_temp = 35,35\n; curr_bed_type = Cool Plate\n; eng_plate_temp = 0,0\n"
            "; filament_colour = #E4002B;#00A651\n; filament_type = PLA;PETG\n; hot_plate_temp = 65,65\n"
            "; layer_height = 0.2\n; nozzle_diameter = 0.4\n; nozzle_temperature = 220,250\n"
            "; printer_model = Example Printer Y\n; CONFIG_BLOCK_END\n\n; EXECUTABLE_BLOCK_START\n" + BODY
            + "; EXECUTABLE_BLOCK_END\n")


def cura():
    return (";FLAVOR:Marlin\n;TIME:6666\n;Filament used: 0m\n;Layer height: 0.2\n;MINX:2.14748e+06\n"
            ";TARGET_MACHINE.NAME:Example Cura Printer\n\n;Generated with Cura_SteamEngine 99.99.9\nM140 S60\n"
            + "".join(f";LAYER:{i}\n;TIME_ELAPSED:{i * 17.5:.6f}\n" + BODY[:60] for i in range(1, 5)) + ";End of Gcode\n")


def no_marker():
    return "; written by hand\nG28\nG1 X10 Y10 F3000\n; layer_height = 0.2\n; estimated printing time (normal mode) = 1h 0m 0s\nM84\n"


def crc_block(kind, compression, params, data, uncompressed=None):
    uncompressed = len(data) if uncompressed is None else uncompressed
    head = struct.pack("<HHI", kind, compression, uncompressed)
    if compression:
        head += struct.pack("<I", len(data))
    body = head + params + data
    return body + struct.pack("<I", zlib.crc32(body) & 0xFFFFFFFF)


def bgcode():
    meta = lambda text: text.encode()
    ini = lambda pairs: "".join(f"{k}={v}\n" for k, v in pairs)
    printer = ini([("printer_model", "Example Printer Z"), ("filament_type", "PLA;PETG"), ("nozzle_diameter", "0.4,0.4"),
                   ("bed_temperature", "60,70"), ("layer_height", "0.2"), ("temperature", "215,235"),
                   ("extruder_colour", ";"), ("filament used [mm]", "1372.73, 1371.79"),
                   ("filament used [g]", "4.09, 4.19"), ("filament used [cm3]", "3.30, 3.30"),
                   ("estimated printing time (normal mode)", "39m 55s")])
    printm = ini([("total toolchanges", "99"), ("filament used [mm]", "1372.73, 1371.79"),
                  ("filament used [cm3]", "3.30, 3.30"), ("filament used [g]", "4.09, 4.19"),
                  ("total filament used [g]", "8.28"), ("estimated printing time (normal mode)", "39m 55s"),
                  ("estimated first layer printing time (normal mode)", "1m 35s")])
    slicer = ini([("filament_colour", "#E4002B;#00AA00"), ("filament_type", "PLA;PETG"), ("layer_height", "0.2")])
    out = b"GCDE" + struct.pack("<IH", 1, 1)
    out += crc_block(0, 0, struct.pack("<H", 0), meta("Producer=PrusaSlicer 99.9.9+linux-x64-GTK3\n"))
    out += crc_block(3, 0, struct.pack("<H", 0), meta(printer))
    out += crc_block(5, 0, struct.pack("<HHH", 2, 16, 16), b"qoif-not-read")
    out += crc_block(5, 0, struct.pack("<HHH", 0, 220, 124), png(2, 2))
    out += crc_block(4, 1, struct.pack("<H", 0), zlib.compress(meta(printm)), len(meta(printm)))
    out += crc_block(2, 1, struct.pack("<H", 0), zlib.compress(meta(slicer)), len(meta(slicer)))
    for _ in range(2):
        out += crc_block(1, 0, struct.pack("<H", 0), b"G1 X1 Y1\n" * 4)
    return out


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    target = os.path.join(here, "gcode")
    os.makedirs(target, exist_ok=True)
    files = {
        "prusa_one_filament.gcode": prusa(False), "prusa_two_filaments.gcode": prusa(True),
        "orca_style.gcode": orca(), "orca_header_only.gcode": orca_header_only(), "bambu_style.gcode": bambu(),
        "cura_style.gcode": cura(), "no_marker.gcode": no_marker(),
    }
    for name, text in files.items():
        with open(os.path.join(target, name), "w", newline="\n") as f:
            f.write(text)
    with open(os.path.join(target, "prusa_binary.bgcode"), "wb") as f:
        f.write(bgcode())


if __name__ == "__main__":
    main()
